<style>
:root{--dl-ink:#0b1c12;--dl-forest:#102b1b;--dl-forest-2:#193d25;--dl-olive:#3f5f2c;--dl-olive-2:#587438;--dl-amber:#df9410;--dl-cream:#f3eee2;--dl-line:#c9d0c5}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:'Be Vietnam Pro',sans-serif;color:var(--dl-ink);background:#fff}.dl-wrap{width:min(1180px,calc(100% - 40px));margin:auto}.dl-head-top{background:#f9f7f1;padding:15px 0}.dl-head-top .dl-wrap{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:25px}.dl-contacts{display:flex;gap:18px;flex-wrap:wrap}.dl-contacts a,.dl-search button,.dl-actions a,.dl-actions button{color:inherit;text-decoration:none}.dl-contacts i{color:var(--dl-amber);margin-right:7px}.dl-logo{display:flex;align-items:center;justify-content:center;text-decoration:none;color:var(--dl-forest);font-size:24px;font-weight:800}.dl-logo img{width:150px;height:62px;object-fit:contain}.dl-logo i{color:var(--dl-amber);margin-right:8px}.dl-search{display:flex;justify-self:end;border:2px solid var(--dl-olive);border-radius:8px;overflow:hidden;width:min(100%,300px);background:#fff}.dl-search input{width:100%;border:0;padding:12px 14px;outline:none}.dl-search button{width:48px;border:0;background:#fff;font-size:18px}.dl-nav-bar{background:var(--dl-forest);color:#fff}.dl-nav-bar .dl-wrap{display:flex;align-items:center;gap:22px;min-height:68px}.dl-nav-bar nav{display:flex;align-items:center;justify-content:center;gap:31px;flex:1}.dl-nav-bar nav a{color:#fff;text-decoration:none;font-weight:600;font-size:14px}.dl-nav-bar nav a:hover{color:#ffc14d}.dl-actions{display:flex;align-items:center;gap:10px}.dl-actions>a,.dl-actions>button{display:grid;place-items:center;width:42px;height:42px;border:1px solid #ffffff66;border-radius:50%;background:transparent;color:#fff}.dl-actions .dl-book{display:flex;width:auto;border:0;border-radius:7px;padding:0 17px;background:var(--dl-amber);font-weight:800;gap:8px}.dl-menu{display:none}.dl-language{position:fixed;right:0;top:42%;z-i