n:center}.dl-reason-grid article{padding:20px 30px}.dl-reason-grid i{font-size:58px;color:var(--dl-olive)}.dl-reason-grid h3{font-size:23px;text-transform:uppercase;color:var(--dl-forest);margin:20px 0 10px}.dl-reason-grid p{line-height:1.7;color:#59615b}.dl-hotline{display:flex;align-items:center;justify-content:center;gap:25px;margin-top:35px}.dl-hotline:before,.dl-hotline:after{content:"";height:1px;background:var(--dl-olive);flex:1}.dl-hotline span{text-transform:uppercase;font-weight:700}.dl-hotline a{color:#b46f00;font-size:37px;font-weight:800;text-decoration:none}.dl-product-layout{display:grid;grid-template-columns:34% 66%;background:var(--dl-forest);border-radius:18px;overflow:hidden}.dl-product-promo{min-height:520px;background-size:cover;background-position:center;display:flex;flex-direction:column;justify-content:end;padding:35px;color:#fff}.dl-product-promo b{font-size:45px}.dl-product-promo span{font-size:18px}.dl-product-grid{display:grid;grid-template-columns:repeat(3,1fr);background:#fff}.dl-product-card{border-left:1px solid #dde2dc;padding:22px;display:flex;flex-direction:column}.dl-product-card>a{height:280px}.dl-product-card img{width:100%;height:100%;object-fit:contain}.dl-product-card h3{font-size:16px;line-height:1.5}.dl-product-card h3 a{color:var(--dl-ink);text-decoration:none}.dl-product-card b{font-size:21px;color:var(--dl-olive)}.dl-product-card del{color:#999}.dl-cart{display:flex;justify-content:space-between;margin-top:15px;padding:13px 15px;background:var(--dl-amber);color:#111;text-decoration:none;font-weight:700;border-radius:6px}.dl-gallery{background:#f7f7f4}.dl-gallery-grid{display:grid;grid-template-columns:1fr 2fr 1fr;gap:16px}.dl-gallery figure{margin:0;height:410px;position:relative;overflow:hidden;border-radius:15px}.dl-gallery img{width:100%;height:100%;object-fit:cover;transition:.4s}.dl-gallery figure:hover img{transform:scale(1.04)}.dl-gallery figcaption{position:absolute;left:18px;bottom:18px;color:#fff;background:#092015dc;padding:9px 13px;border-radius:5px}.dl-news-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:34px}.dl-news-main img{width:100%;height:400px;object-fit:cover;border-radius:15px}.dl-news h3{color:var(--dl-forest);line-height:1.45}.dl-news p{color:#626b64;line-height:1.65}.dl-news time{color:#a86a00;font-weight:700;display:block;margin-top:12px}.dl-news a{color:var(--dl-forest);font-weight:700;text-decoration:none}.dl-news-list{display:grid;gap:18px}.dl-news-list article{display:grid;grid-template-columns:190px 1fr;gap:18px;border-bottom:1px solid #ddd;padding-bottom:17px}.dl-news-list img{width:100%;height:145px;object-fit:cover;border-radius:9px}.dl-news-list h3{margin:5px 0;font-size:17px}.dl-news-list p{margin:5px 0;font-size:14px}.dl-faq{background:linear-gradient(90deg,#193b25ee,#2f5a31eb),url('https://images.unsplash.com/photo-1508873699372-7aeab60b44ab?auto=format&fit=crop&w=1800&q=80') center/cover;color:#fff}.dl-faq-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:50px;align-items:center}.dl-accordion{background:#fff;color:var(--dl-ink);border-radius:14px;padding:16px}.dl-accordion article{border-bottom:1px solid #ddd}.dl-accordion button{width:100%;border:0;background:none;padding:20px 10px;display:flex;justify-content:space-between;font:inherit;font-weight:700;text-align:left}.dl-accordion article>div{display:grid;grid-template-rows:0fr;transition:.3s}.dl-accordion article>div p{overflow:hidden;margin:0;padding:0 10px;line-height:1.7}.dl-accordion article.is-open>div{grid-template-rows:1fr}.dl-accordion article.is-open>div p{padding-bottom:20px}.dl-accordion article.is-open button{color:#a76700}.dl-accordion article.is-open button i{transform:rotate(180deg)}.dl-faq-media{text-align:center}.dl-faq-media img{width:100%;height:370px;object-fit:cover;border-radius:25px}.dl-faq-media a{display:inline-flex;background:var(--dl-amber);color:#111;padding:16px 26px;border-radius:30px;text-decoration:none;font-weight:800;transform:translateY(-25px)}.